import {initShared,initModel,openContact,contactLinks,$,$$} from './shared.js';
import {fetchProperties} from './api.js';
import {escapeHtml as esc,imageSrc} from './catalogue.js';
initShared();initModel();
$$('[data-place]').forEach(b=>b.addEventListener('click',()=>location.href=`biens.html?place=${encodeURIComponent(b.dataset.place)}`));
$$('[data-faq-search]').forEach(input=>input.addEventListener('input',()=>{let visible=0;const term=input.value.toLocaleLowerCase('fr');$$('.faq-list details').forEach(d=>{d.hidden=!d.textContent.toLocaleLowerCase('fr').includes(term);if(!d.hidden)visible++});$('#faq-count').textContent=`${visible} réponse${visible>1?'s':''}` }));
const host=$('#detail-page');
if(host){const id=new URLSearchParams(location.search).get('id');
  if(!id){host.innerHTML='<div class="empty-state"><h1>Choisissez votre prochaine adresse.</h1><p>Retrouvez les biens dans notre catalogue.</p><a class="button button-navy" href="biens.html">Explorer les biens</a></div>'}
  else fetchProperties().then(items=>{
    const p=items.find(p=>p.id===id);if(!p){host.innerHTML='<div class="empty-state"><h1>Cette adresse n’est plus disponible.</h1><p>Elle a pu être retirée du catalogue.</p><a class="button button-navy" href="biens.html">Revenir au catalogue</a></div>';return}
    document.title=`${p.title} — MAFOSS Immobilier`;
    const nf=new Intl.NumberFormat('fr-SN'),local=[p.district,p.city,p.region].filter(Boolean).filter((x,i,a)=>a.indexOf(x)===i).join(' · ');
    host.innerHTML=`<div class="breadcrumb"><a href="index.html">Accueil</a><span>/</span><a href="biens.html">Nos biens</a><span>/</span><span>${esc(p.type)}</span></div><div class="detail-heading"><div><p class="eyebrow">${esc(p.transaction.toUpperCase())} · ${esc(p.type.toUpperCase())}${p.demo?' · DÉMONSTRATION':''}</p><h1>${esc(p.title)}</h1><p>${esc(local)} · Sénégal</p></div><div class="detail-actions"><button class="button button-outline" id="save-property" aria-pressed="false">♡ Enregistrer</button><button class="button button-outline" id="share-property">Copier le lien ↗</button></div></div><figure class="detail-hero"><img src="${esc(imageSrc(p))}" alt="${esc(p.visual)} — ${esc(p.title)}"><figcaption>${esc(p.visual)}${p.demo?' · bien fictif · aucune propriété réelle représentée':''}</figcaption></figure><div class="detail-layout"><article><div class="detail-stats"><div><strong>${nf.format(p.area)} m²</strong><small>Superficie${p.demo?' fictive':''}</small></div><div><strong>${p.rooms||'—'}</strong><small>${p.type==='Bureau'?'Espaces':'Chambres'}</small></div><div><strong>${p.baths||'—'}</strong><small>Salles d’eau</small></div></div><h2>Un lieu à découvrir.</h2><p class="readable">${esc(p.description)}</p>${p.feature?`<p class="feature-pill">${esc(p.feature)}</p>`:''}<h3>Les repères du bien</h3><dl class="property-facts"><div><dt>Région</dt><dd>${esc(p.region)}</dd></div><div><dt>Ville</dt><dd>${esc(p.city)}</dd></div>${p.district?`<div><dt>Quartier</dt><dd>${esc(p.district)}</dd></div>`:''}<div><dt>Transaction</dt><dd>${esc(p.transaction)}</dd></div><div><dt>Référence</dt><dd>${esc(p.id)}</dd></div></dl>${p.demo?'<aside class="demo-disclosure"><strong>Fiche de démonstration</strong><p>Les caractéristiques et visuels de ce bien sont fictifs. Ils ne constituent ni une offre de vente, ni une disponibilité, ni une réalisation de MAFOSS. Aucun document foncier n’a été vérifié.</p></aside>':''}<h3>Avant de vous projeter</h3><p class="readable">Échangez avec l’équipe sur votre recherche, le budget en FCFA, les informations disponibles et les prochaines étapes. Les conditions précises se confirment directement avec votre interlocuteur.</p></article><aside class="enquiry-card"><p class="eyebrow">VOTRE PROJET</p><h2>Prix sur<br><em>demande.</em></h2><p>Parlons du lieu que vous recherchez et des conditions de votre projet.</p><button class="button button-navy" id="property-enquiry">${p.demo?'Un projet similaire':'Demander des informations'} ↗</button><div class="contact-channels">${contactLinks(`Bonjour, je souhaite des informations sur « ${p.title} » (réf. ${p.id}).`,'Demande immobilière '+p.id)}</div><a class="small-link" href="confidentialite.html">Vos données et votre confidentialité</a></aside></div><div class="section-heading related-heading"><h2>Continuez<br><em>l’exploration.</em></h2><a class="text-link" href="biens.html">Tous nos biens ↗</a></div><div class="related-grid">${items.filter(q=>q.id!==id).sort((a,b)=>(b.city===p.city)-(a.city===p.city)).slice(0,3).map(q=>`<a class="related-card" href="bien.html?id=${encodeURIComponent(q.id)}"><img src="${esc(imageSrc(q))}" alt="${esc(q.visual)}" loading="lazy"><small>${esc(q.district||q.city)}${q.demo?' · FICTIF':''}</small><h3>${esc(q.title)}</h3><span>${nf.format(q.area)} m² · Prix sur demande ↗</span></a>`).join('')}</div>`;
    let saved=[];try{saved=JSON.parse(localStorage.getItem('mafoss-selection')||'[]');if(!Array.isArray(saved))saved=[]}catch{}
    const sync=()=>{const active=saved.includes(id);$('#save-property').textContent=active?'♥ Enregistré':'♡ Enregistrer';$('#save-property').setAttribute('aria-pressed',active)};sync();
    $('#save-property').onclick=()=>{saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('mafoss-selection',JSON.stringify(saved))}catch{}sync()};
    $('#share-property').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);$('#share-property').textContent='Lien copié ✓'}catch{$('#share-property').textContent='Copiez le lien dans la barre d’adresse'}};
    $('#property-enquiry').onclick=()=>{openContact(p.id,p.transaction==='Vente'?'Acheter un bien':'Louer un bien');const f=$('#contact-form').elements;f.location.value=local;f.message.value=`Je souhaite ${p.demo?'préparer un projet similaire à':'des informations sur'} « ${p.title} » (réf. ${p.id}).`};
  }).catch(()=>{host.innerHTML='<div class="empty-state"><h1>Le catalogue est indisponible.</h1><p>Réessayez dans un instant ou appelez le +221 77 421 24 84.</p><button class="button button-navy" onclick="location.reload()">Réessayer</button></div>'});
}
